"""Check two arrays for tolerance [1,2,3]==[1,2,3]; but [1,3,2]!=[1,2,3]
    Args:
        A, B (lists): 1-D list of values for approximate equality comparison
        tolerance: numerical precision for equality condition

    Returns:
        boolean
    """
def are_eq(A: Any, B: Any, tolerance: Any = 0.0001) -> object {
    are_eq = True;
    if (len(A) != len(B)) {
        are_eq = False;
    } else {
        i = 0;
        while (i < len(A)) {
            if (abs((A[i] - B[i])) > tolerance) {
                are_eq = False;
            }
            i = i + 1;
        }
    }
    return are_eq;
}

"""
    Get lats and longs to mark on map
    :param minv:
    :type minv: float
    :param maxv:
    :type maxv: float
    :param stepv:
    :type stepv: int
    :return:
    :rtype: list
    """
def getcardinals(minv: Any, maxv: Any, stepv: Any) -> object {
    cardinals = [
        val
        for val in range(minv, maxv)
        if ((val % stepv) == 0)
    ];
    if (len(cardinals) > 10) {
        return [
            cardinal[1]
            for cardinal in enumerate(cardinals)
            if ((cardinal[0] % 2) > 0)
        ];
    }
    return cardinals;
}

"""Python's 'in' keyword performs a linear search on arrays.
    Given the circumstances of storing sorted arrays, it's better
    for Nyx to use a binary search.

    Arguments:
    key - filter for objects in the array
    start - 0-indexed starting marker on the array to search
    end - exclusive ending marker on the array to search
    """
def binary_search(
    array: Any,
    query: Any,
    key: Any = lambda (a: Any) { a; },
    start: Any = 0,
    end: Any = -1
) -> object {
    if ((array is None) or (len(array) == 0)) {
        return None;
    }
    if (end == -1) {
        end = len(array);
    } elif (start >= end) {
        return None;
    }
    mid = int((start + ((end - start) / 2)));
    compare_to = key(array[mid]);
    if (query < compare_to) {
        return binary_search(array, query, key, start, mid);
    } elif (query > compare_to) {
        return binary_search(array, query, key, (mid + 1), end);
    } else {
        return array[mid];
    }
}

